import{_ as e,c as t,o as a,ae as r}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"RESTORING EQUALITY OF OPPORTUNITY AND MERITOCRACY","description":"","frontmatter":{"title":"RESTORING EQUALITY OF OPPORTUNITY AND MERITOCRACY","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/restoring-equality-of-opportunity-and-meritocracy/","publishDate":"2025-04-23T18:58:10-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-23-restoring-equality-of-opportunity-and-meritocracy.md","filePath":"executive-orders/2025-04-23-restoring-equality-of-opportunity-and-meritocracy.md"}'),o={name:"executive-orders/2025-04-23-restoring-equality-of-opportunity-and-meritocracy.md"};function n(s,i,l,d,p,c){return a(),t("div",null,i[0]||(i[0]=[r('<h1 id="restoring-equality-of-opportunity-and-meritocracy" tabindex="-1">RESTORING EQUALITY OF OPPORTUNITY AND MERITOCRACY <a class="header-anchor" href="#restoring-equality-of-opportunity-and-meritocracy" aria-label="Permalink to &quot;RESTORING EQUALITY OF OPPORTUNITY AND MERITOCRACY&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/restoring-equality-of-opportunity-and-meritocracy/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/restoring-equality-of-opportunity-and-meritocracy/</a></p><p>Published: Wednesday, April 23, 2025</p><ul><li>The order affirms the principle that all citizens should be treated equally under the law, emphasizing equality of opportunity over equal outcomes.</li><li>Criticism of disparate-impact liability, which presumes discrimination based on outcome differences among races or groups, is highlighted as detrimental to meritocracy and individual assessment.</li><li>The order argues that disparate-impact liability inhibits businesses from making merit-based hiring decisions, ultimately hindering job opportunities for individuals.</li><li>There is a commitment to eliminate disparate-impact liability to uphold constitutional values and civil rights laws.</li><li>Revocation of prior Presidential approvals relating to Title VI regulations that enabled disparate-impact liability is mandated.</li><li>Agencies are directed to deprioritize enforcement of laws incorporating disparate-impact liability.</li><li>The Attorney General is tasked with repealing or amending regulations that contemplate disparate-impact liability, with a report to the President required within 30 days.</li><li>A 45-day timeline is set for assessing ongoing civil rights investigations or suits reliant on disparate-impact liability theories, with appropriate actions to be taken.</li><li>An evaluation of existing consent judgments related to disparate-impact liability is required within 90 days.</li><li>The Attorney General will assess whether federal authority can preempt state laws imposing disparate-impact liability.</li><li>Guidance on promoting equal access to employment without degree requirements is to be issued by the Attorney General and the Equal Employment Opportunity Commission.</li><li>The order’s validity is independent of its provisions; if one is invalidated, the rest remain effective.</li><li>Clarifications are made regarding the authority and functions of executive departments and the need for law compliance in implementation.</li><li>The order does not create enforceable rights for individuals against the U.S. or its entities.</li></ul>',4)]))}const h=e(o,[["render",n]]);export{m as __pageData,h as default};
